package org.eclipse.rdf4j.query.algebra.evaluation.impl;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertSame;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.mockito.Mockito.CALLS_REAL_METHODS;
import static org.mockito.Mockito.mock;

import java.util.concurrent.atomic.AtomicInteger;

import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.query.Dataset;
import org.eclipse.rdf4j.query.QueryExecutionPolicy;
import org.eclipse.rdf4j.query.algebra.QueryRoot;
import org.eclipse.rdf4j.query.algebra.SingletonSet;
import org.eclipse.rdf4j.query.algebra.ValueConstant;
import org.eclipse.rdf4j.query.algebra.evaluation.EvaluationStrategy;
import org.eclipse.rdf4j.query.algebra.evaluation.TripleSource;
import org.eclipse.rdf4j.query.algebra.evaluation.util.QueryEvaluationUtility;
import org.junit.jupiter.api.Test;

class QueryExecutionPolicyTest {

	@Test
	void directScalarPreparationFreezesPolicy() {
		DefaultEvaluationStrategy strategy = new DefaultEvaluationStrategy(new EmptyTripleSource(), null);
		strategy.precompile(new ValueConstant(SimpleValueFactory.getInstance().createLiteral("standalone")),
				new QueryEvaluationContext.Minimal(null));
		assertThrows(IllegalStateException.class,
				() -> strategy.setQueryExecutionPolicy(QueryExecutionPolicy.EXPERIMENTAL));
		assertSame(QueryExecutionPolicy.DEFAULT, strategy.getQueryExecutionPolicy());
	}

	@Test
	void compilationInsideAnAlreadyPreparedPhaseStillFreezesTheStrategyPolicy() {
		DefaultEvaluationStrategy strategy = new DefaultEvaluationStrategy(new EmptyTripleSource(), null);
		QueryRoot root = new QueryRoot(new SingletonSet());
		QueryEvaluationUtility.withPreparedQuerySafetySnapshot(root, PreparedValuesSnapshot::newPreparation,
				strategy::precompile);
		assertThrows(IllegalStateException.class,
				() -> strategy.setQueryExecutionPolicy(QueryExecutionPolicy.EXPERIMENTAL));
	}

	@Test
	void factoryPolicyOverloadPreservesTheExistingCustomDispatch() {
		AtomicInteger calls = new AtomicInteger();
		DefaultEvaluationStrategyFactory factory = new DefaultEvaluationStrategyFactory() {
			@Override
			public EvaluationStrategy createEvaluationStrategy(Dataset dataset, TripleSource source,
					EvaluationStatistics statistics) {
				calls.incrementAndGet();
				return new DefaultEvaluationStrategy(source, dataset, null);
			}
		};
		EvaluationStrategy first = factory.createEvaluationStrategy(null, new EmptyTripleSource(),
				new EvaluationStatistics(), QueryExecutionPolicy.EXPERIMENTAL);
		EvaluationStrategy second = factory.createEvaluationStrategy(null, new EmptyTripleSource(),
				new EvaluationStatistics(), QueryExecutionPolicy.DEFAULT);
		assertEquals(2, calls.get());
		assertSame(QueryExecutionPolicy.EXPERIMENTAL, first.getQueryExecutionPolicy());
		assertSame(QueryExecutionPolicy.DEFAULT, second.getQueryExecutionPolicy());
		assertThrows(IllegalStateException.class, () -> first.setQueryExecutionPolicy(QueryExecutionPolicy.DEFAULT));
	}

	@Test
	void unsupportedCustomStrategiesAcceptDefaultAndRejectOptInExplicitly() {
		EvaluationStrategy strategy = mock(EvaluationStrategy.class, CALLS_REAL_METHODS);
		strategy.setQueryExecutionPolicy(QueryExecutionPolicy.DEFAULT);
		assertSame(QueryExecutionPolicy.DEFAULT, strategy.getQueryExecutionPolicy());
		assertThrows(UnsupportedOperationException.class,
				() -> strategy.setQueryExecutionPolicy(QueryExecutionPolicy.EXPERIMENTAL));
	}
}
